type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string
var WsFirstFlag string
var WsPrevBranch string
var WsPrevAcct string
var WsBal decimal.Decimal
var WsBranchTot decimal.Decimal
var WsGrandTot decimal.Decimal
var WsSkipped int64
