var WsBalEd string
var WsTotEd string

var ledgerRecords []LedgerRec
var ledgerIndex int
var currentRec LedgerRec
var inputDone bool

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatEditedUnsigned(val decimal.Decimal, picture string) string {
	// picture without leading sign, contains Z,9,',' , '.'
	pic := []rune(picture)
	dotPos := -1
	for i, c := range pic {
		if c == '.' {
			dotPos = i
			break
		}
	}
	fracDigits := 0
	if dotPos != -1 {
		fracDigits = len(pic) - dotPos - 1
	}
	// scale handling
	scale := int32(fracDigits)
	absVal := val.Abs()
	// truncate toward zero
	absVal = absVal.Truncate(scale)
	// integer slots
	// collect positions of Z/9 before dot
	var intSlotPos []int
	end := len(pic)
	if dotPos != -1 {
		end = dotPos
	}
	for i := 0; i < end; i++ {
		if pic[i] == 'Z' || pic[i] == '9' {
			intSlotPos = append(intSlotPos, i)
		}
	}
	intSlots := len(intSlotPos)

	// get integer and fractional strings
	// Use Shift to get scaled integer
	// intPart value
	shifted := absVal.Shift(scale) // absVal *10^scale
	// For truncation already done, but get integer representation
	// Use IntPart after trunc
	// To avoid float issues, format with string
	// We can get integer part and fractional via splitting
	// Use decimal's string with fixed scale
	// Build intVal and fracVal
	var intValStr string
	var fracValStr string
	if fracDigits > 0 {
		// use Truncate scale already, then get
		// shifted is integer
		s := shifted.Truncate(0).StringFixed(0) // no exponent
		// s may have sign? abs so no
		// ensure positive
		if strings.HasPrefix(s, "-") {
			s = s[1:]
		}
		// pad left with zeros to at least fracDigits+1
		if len(s) <= fracDigits {
			s = strings.Repeat("0", fracDigits+1-len(s)) + s
		}
		intPart := s[:len(s)-fracDigits]
		fracPart := s[len(s)-fracDigits:]
		// strip leading zeros for intPart but keep at least "0"
		intValStr = strings.TrimLeft(intPart, "0")
		if intValStr == "" {
			intValStr = "0"
		} else {
			intValStr = intPart // keep zeros? Actually intPart already has leading zeros trimmed? For digit filling we need raw intPart without trimming? Let's use intPart directly for digit extraction.
			// To handle overflow, we keep intPart as is (without trimming) -> then low-order truncation below will work.
			intValStr = intPart
		}
		// For uniform handling, we will use intPart as integer digits string (maybe with leading zeros)
		// But for suppression we need digits including leading zeros stripped? We need to produce intDigitsStr of length intSlots
		fracValStr = fracPart
		// override intValStr to original intPart for padding logic
		intValStr = intPart
	} else {
		s := absVal.Truncate(0).StringFixed(0)
		if strings.HasPrefix(s, "-") {
			s = s[1:]
		}
		if s == "" {
			s = "0"
		}
		intValStr = s
		fracValStr = ""
	}

	// Prepare output initialized with picture chars
	out := make([]rune, len(pic))
	copy(out, pic)

	// Fill fractional part
	if dotPos != -1 {
		for i := 0; i < fracDigits; i++ {
			pos := dotPos + 1 + i
			if i < len(fracValStr) {
				out[pos] = rune(fracValStr[i])
			} else {
				out[pos] = '0'
			}
		}
	}

	// Prepare integer digits string of length intSlots, with overflow low-order
	// intValStr may have leading zeros; we need to keep only low-order intSlots digits
	// intValStr is decimal digits of integer part (e.g., "0", "123")
	var intDigitsPadded string
	if len(intValStr) > intSlots {
		intDigitsPadded = intValStr[len(intValStr)-intSlots:]
	} else if len(intValStr) < intSlots {
		intDigitsPadded = strings.Repeat("0", intSlots-len(intValStr)) + intValStr
	} else {
		intDigitsPadded = intValStr
	}
	// Fill integer slots from rightmost
	for idx := intSlots - 1; idx >= 0; idx-- {
		pos := intSlotPos[idx]
		ch := intDigitsPadded[idx]
		out[pos] = rune(ch)
	}

	// Apply Z suppression
	// Determine for each integer slot whether it should be suppressed
	// nonzeroSeen tracks if any non-zero digit has been seen in integer part (after filling)
	// For suppression we look at digits in out at slot positions
	// Find first non-zero position
	firstNonZero := -1
	for i, p := range intSlotPos {
		if out[p] != '0' {
			firstNonZero = i
			break
		}
	}
	// If all zeros, then the last slot (which is a '9' in these pictures) should remain '0'
	// So we suppress only up to before last slot
	for i, p := range intSlotPos {
		picChar := pic[p]
		if picChar == 'Z' {
			if firstNonZero == -1 {
				// all zero -> suppress all Z
				out[p] = ' '
			} else if i < firstNonZero {
				out[p] = ' '
			} else {
				// keep digit (even if zero after first non-zero, keep)
			}
		} else {
			// '9' always keep
		}
	}
	// Commas in suppressed zone become spaces
	// A comma is suppressed if no non-zero has appeared before it
	// Determine for each comma its position relative to int slots
	for i, c := range pic {
		if c == ',' {
			// find how many int slots are before this comma
			// find index of first slot after comma
			// simpler: if i < dotPos and preceding integer part is still suppressed
			// Check if all integer slots before comma are suppressed (or zero Z)
			beforeNonZero := false
			// count slots before comma that are not suppressed (i.e., have non-zero or are '9' with non-zero? simplistic use firstNonZero)
			// If firstNonZero == -1 -> all suppressed, so comma suppressed
			// Otherwise, find position of firstNonZero slot pos
			if firstNonZero == -1 {
				out[i] = ' '
			} else {
				firstPos := intSlotPos[firstNonZero]
				if i < firstPos {
					out[i] = ' '
				}
			}
			_ = beforeNonZero
		}
	}
	return string(out)
}

func formatEdited(val decimal.Decimal, picture string) string {
	if strings.HasPrefix(picture, "-") {
		signChar := ' '
		if val.IsNegative() && !val.IsZero() {
			signChar = '-'
		}
		restPic := picture[1:]
		body := formatEditedUnsigned(val, restPic)
		return string(signChar) + body
	}
	return formatEditedUnsigned(val, picture)
}

func storeField(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// truncate toward zero to scale
	v := val.Truncate(scale)
	totalDigits := intDigits + int(scale)
	modulus := decimal.New(1, int32(totalDigits)) // 10^totalDigits
	scaled := v.Shift(scale).Truncate(0)
	if scaled.Abs().GreaterThanOrEqual(modulus) {
		abs := scaled.Abs()
		rem := abs.Mod(modulus)
		if scaled.IsNegative() {
			scaled = rem.Neg()
		} else {
			scaled = rem
		}
		v = scaled.Shift(-scale)
	}
	return v
}

func storeBal(v decimal.Decimal) decimal.Decimal {
	return storeField(v, 7, 2)
}
func storeBranchTot(v decimal.Decimal) decimal.Decimal {
	return storeField(v, 9, 2)
}
func storeGrandTot(v decimal.Decimal) decimal.Decimal {
	return storeField(v, 9, 2)
}
func storeSkipped(v int64) int64 {
	// PIC 99
	if v >= 100 || v < 0 {
		v = v % 100
		if v < 0 {
			v += 100
		}
	}
	return v
}

func displayLine(parts ...string) {
	var sb strings.Builder
	for _, p := range parts {
		sb.WriteString(p)
	}
	fmt.Println(sb.String())
}

func formatWsSkipped(v int64) string {
	// PIC 99 zero padded width 2
	if v < 0 {
		v = -v
	}
	v = v % 100
	return fmt.Sprintf("%02d", v)
}

// File reading

func loadLedger() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			ledgerRecords = nil
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	// LINE SEQUENTIAL: split on lines
	// Use bufio to handle \r\n
	s := string(data)
	// scanner that preserves empty lines?
	// We'll split using bufio.Scanner
	sc := bufio.NewScanner(strings.NewReader(s))
	// increase buffer
	buf := make([]byte, 0, 64*1024)
	sc.Buffer(buf, 10*1024*1024)
	for sc.Scan() {
		line := sc.Text()
		// Remove trailing \r if present (scanner already strips \n, but \r remains if CRLF)
		if strings.HasSuffix(line, "\r") {
			line = strings.TrimSuffix(line, "\r")
		}
		recStr := padRight(line, 14)
		brBranch := recStr[0:2]
		brAcct := recStr[2:6]
		brType := recStr[6:7]
		brAmtStr := recStr[7:14]
		// brAmtStr should be digits, may contain spaces
		trim := strings.TrimSpace(brAmtStr)
		var amt decimal.Decimal
		if trim == "" {
			amt = decimal.NewFromInt(0)
		} else {
			// remove any spaces inside? assume digits
			// Keep only digits and sign?
			clean := ""
			for _, ch := range trim {
				if ch >= '0' && ch <= '9' {
					clean += string(ch)
				}
			}
			if clean == "" {
				clean = "0"
			}
			n := int64(0)
			// clean length up to 7, fits int64
			for _, ch := range clean {
				n = n*10 + int64(ch-'0')
			}
			// But if original had more than 7? Still use clean
			// Pad/truncate to 7 digits? The field is 7 digits, but if line longer? Use what we have.
			amt = decimal.New(n, -2)
			// However if original string had spaces leading, still same
			// If string contained non-digit, treat as 0? already filtered
		}
		ledgerRecords = append(ledgerRecords, LedgerRec{
			BrBranch: brBranch,
			BrAcct:   brAcct,
			BrType:   brType,
			BrAmt:    amt,
		})
	}
}

func READPARA() {
	if ledgerIndex >= len(ledgerRecords) {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	currentRec = ledgerRecords[ledgerIndex]
	ledgerIndex++
	inputDone = false
	WsEofFlag = "N"
}

func PROCESSPARA() {
	if WsFirstFlag == "Y" {
		WsPrevBranch = currentRec.BrBranch
		WsPrevAcct = currentRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if currentRec.BrBranch != WsPrevBranch {
			ACCTBREAKPARA()
			BRANCHBREAKPARA()
			WsPrevBranch = currentRec.BrBranch
			WsPrevAcct = currentRec.BrAcct
		} else {
			if currentRec.BrAcct != WsPrevAcct {
				ACCTBREAKPARA()
				WsPrevAcct = currentRec.BrAcct
			}
		}
	}
	POSTPARA()
	READPARA()
}

func POSTPARA() {
	WsAmtEd = formatEdited(currentRec.BrAmt, "ZZ,ZZ9.99")
	switch currentRec.BrType {
	case "D":
		WsBal = storeBal(WsBal.Add(currentRec.BrAmt))
		displayLine(currentRec.BrAcct, " D ", WsAmtEd)
	case "C":
		WsBal = storeBal(WsBal.Sub(currentRec.BrAmt))
		displayLine(currentRec.BrAcct, " C ", WsAmtEd)
	default:
		WsSkipped = storeSkipped(WsSkipped + 1)
		displayLine(currentRec.BrAcct, " ? SKIPPED")
	}
}

func ACCTBREAKPARA() {
	WsBalEd = formatEdited(WsBal, "-Z,ZZZ,ZZ9.99")
	displayLine("  ACCOUNT ", WsPrevAcct, " BALANCE:", WsBalEd)
	WsBranchTot = storeBranchTot(WsBranchTot.Add(WsBal))
	WsBal = decimal.NewFromInt(0)
}

func BRANCHBREAKPARA() {
	WsTotEd = formatEdited(WsBranchTot, "-ZZZ,ZZZ,ZZ9.99")
	displayLine(" BRANCH ", WsPrevBranch, " TOTAL:", WsTotEd)
	WsGrandTot = storeGrandTot(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.NewFromInt(0)
}

func GRANDPARA() {
	WsTotEd = formatEdited(WsGrandTot, "-ZZZ,ZZZ,ZZ9.99")
	displayLine("GRAND TOTAL:", WsTotEd)
	displayLine("SKIPPED: ", formatWsSkipped(WsSkipped))
}

func MAINPARA() {
	READPARA()
	for !inputDone {
		PROCESSPARA()
	}
	if WsFirstFlag != "Y" {
		ACCTBREAKPARA()
		BRANCHBREAKPARA()
	}
	GRANDPARA()
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevBranch = strings.Repeat(" ", 2)
	WsPrevAcct = strings.Repeat(" ", 4)
	WsBal = decimal.NewFromInt(0)
	WsBranchTot = decimal.NewFromInt(0)
	WsGrandTot = decimal.NewFromInt(0)
	WsSkipped = 0

	loadLedger()
	MAINPARA()
}
